// Transcoding trigger
public async Task EnqueueTranscode(string videoId) {
    await _mediaConvert.JobTemplate = "System-HLS-1080p";
    await _mediaConvert.CreateJobAsync(new CreateJobRequest {
        Role = _mediaConvertRole.Arn,
        Queue = _queue.Arn,
        Settings = new JobSettings {
            OutputGroups = new [] {
                new OutputGroup {
                    Name = "Apple HLS",
                    OutputGroupSettings = new OutputGroupSettings {
                        Type = OutputGroupType.HLS_GROUP_SETTINGS,
                        HlsGroupSettings = new HlsGroupSettings { ... }
                    }
                }
            }
        }
    });
}
